let state=loadState(), view='today', session=null, timer=null, walker=null, walkStats=null, gpsMode='walk', wakeLock=null, syncMessage='', guideName=null, authMode='signin', publicView='auth', memberDirectory=[], mateRows=[], routeActivity=null, mobileNavOpen=false, installPrompt=null, authBusy=false, liveMap=null, liveLine=null, liveMarker=null, shareActivity=null, shareMapMode='privacy', progressPhotos=[], transformationSelection=[], transformationPreview=null
const nav=[['today','Overview'],['move','Move'],['fuel','Fuel'],['setup','Set Up'],['journey','My Journey']]

const button=(id,label)=>`<button data-view="${id}">${label}</button>`
function brandMark(){return '<span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 120 82"><circle cx="42" cy="19" r="9"/><circle class="lime-person" cx="65" cy="19" r="9"/><path d="M35 32l-7 28h10l4-17 4 17h10l-7-28z"/><path class="lime-person" d="M58 32l-7 28h10l4-17 4 17h10l-7-28z"/><path class="brand-swoop" d="M16 61C27 72 70 66 91 42" fill="none"/><path class="brand-arrow" d="M84 37l20-8-9 20z"/></svg></span>'}
function brandLockup(){return '<span class="brand-assets"><img class="brand-wording-image brand-full-logo" src="/transform_full_logo.png" alt="TRANSFORM — Consistent. Persistent. Targeted."></span>'}
function layout(body){const publicNav=!session?'<button id="vision-link" class="account-action">The Vision</button>':nav.map(x=>button(...x)).join('')+'<button id="sign-out" class="account-action">Sign out</button>';const desktop=session?'<aside class="desktop-sidebar"><nav>'+publicNav+'</nav><div class="sidebar-photo"></div></aside>':'';return `${desktop}<header class="${session?'member-header':''}"><div class="header-bar"><button class="brand" ${session?'data-view="today"':'id="public-home"'}>${brandLockup()}</button>${session?`<button id="menu-toggle" class="menu-toggle" aria-label="Open menu" aria-expanded="${mobileNavOpen}"><span></span><span></span><span></span></button>`:''}</div><nav class="${mobileNavOpen?'open':''}">${publicNav}</nav></header>${syncMessage?`<div class="sync-message">${syncMessage}</div>`:''}<main>${body}</main><footer><strong>CONSISTENT.</strong> <strong>PERSISTENT.</strong> <strong>TARGETED.</strong></footer>`}
function head(k,t,p){return `<section class="head"><p class="eyebrow">${k}</p><h1>${t}</h1><p>${p}</p></section>`}
function resolveWorkout(w){return {...w,exercises:w.slots.map((slot,i)=>{const override=state.exerciseOverrides?.[`${w.id}:${i}`],opts=availableOptions(slot.category,state.equipment||[],levelForWorkout(w.id)),picked=(override&&opts.find(x=>x.name===override))||chooseExercise(slot.category,state.equipment||[],w.id+i,levelForWorkout(w.id));return {name:picked?.name||'Bodyweight movement',category:slot.category,note:picked?.note||'Use a comfortable, controlled range.'}})}}
function today(){
 const w=resolveWorkout(workouts[state.workoutIndex%28]), f=Object.values(state.fuel[todayKey()]||{}).filter(Boolean).length
 return head('TODAY','Show up. <span>That counts.</span>','Do what fits today. The aim is consistency, not a perfect scorecard.')+`
 <section class="dashboard overview-dashboard"><article class="feature"><div><p class="eyebrow">NEXT WORKOUT · ${w.id}/28</p><h2>${w.title}</h2><p>${w.focus} · ${w.minutes} min</p></div>${button('move','Go to Move →')}</article>
 ${[['Active minutes',state.activeMinutes],['Day streak',state.streak],['Healthy choices',f],['Water',state.hydrationByDate?.[todayKey()]||0]].map(x=>`<article class="stat"><strong>${x[1]}</strong><span>${x[0]}</span></article>`).join('')}</section>`}
function move(){
 const w=resolveWorkout(workouts[state.workoutIndex%28])
 return head('MOVE','Your next move.','Follow the sequence, replace it with another activity, or add extra movement. It all counts.')+`
 <section class="cols"><article class="feature workout"><div><p class="eyebrow">WORKOUT ${w.id} OF 28 · ${w.level.toUpperCase()}</p><h2>${w.title}</h2><p>${w.focus} · ${w.exercises.length} exercises · ${w.rounds} rounds</p><strong>~${w.minutes} minutes</strong></div><div class="workout-start"><label><input id="auto-progress" type="checkbox" ${state.autoProgress!==false?'checked':''}> Auto progression</label><button id="start-workout">Start workout →</button></div></article>
 <article class="form"><h3>Track an activity</h3><p class="hint">Track distance, pace and elevation with GPS.</p><div class="gps-buttons"><button data-gps="walk">Walk</button><button data-gps="run">Run</button><button data-gps="ride">Bike Ride</button><button data-gps="hike">Hike</button></div><hr><h3>Swimming</h3><p class="hint">Record a swim by time now; laps and distance are part of the swimming activity model.</p><button id="quick-swim">Log a swim →</button><hr><h3>Log another activity</h3><label>Activity<input id="activity" placeholder="Walk, swim, sport…"></label><label>Active minutes<input id="minutes" type="number" min="1" placeholder="30"></label><button id="log">Add activity</button><p class="hint">Your next workout stays waiting for you.</p></article></section>
 <section class="exercise-preview"><h3>Inside this workout</h3><div>${w.exercises.map((e,i)=>`<span><b>${i+1}</b><button class="exercise-name" data-guide="${e.name}">${e.name}<small>${e.category} · ${['','foundation','developing','stronger'][levelForWorkout(w.id)]}</small></button><button class="swap-exercise" data-swap="${i}" title="Choose another suitable exercise">Swap</button></span>`).join('')}</div></section><section class="history move-together"><p class="eyebrow">TOGETHER</p><h3>Better with a mate.</h3><p>Connect with someone in the programme for accountability. Your workout sequence remains your own.</p>${(()=>{const incoming=mateRows.filter(x=>x.status==='pending'&&x.mate_id===session?.user?.id),accepted=mateRows.filter(x=>x.status==='accepted');return accepted.length?'<p class="success">'+accepted.length+' connected workout mate'+(accepted.length===1?'':'s')+'.</p>':''})()}<div id="incoming-mates">${mateRows.filter(x=>x.status==='pending'&&x.mate_id===session?.user?.id).map(x=>'<div class="mate-request"><span>Workout mate request</span><div><button data-mate-accept="'+x.id+'">Accept</button><button data-mate-decline="'+x.id+'" class="secondary">Decline</button></div></div>').join('')}</div><button id="find-mate" class="text-button">Find a workout mate →</button><div id="mate-panel"></div></section><section class="history"><h3>Recent movement</h3>${state.activities.length?state.activities.slice(-5).reverse().map(a=>`<div><span>${a.name}</span><strong>${a.minutes} min</strong></div>`).join(''):'<p>Nothing logged yet.</p>'}</section>`}
function guideView(name){const w=timer?.workout||resolveWorkout(workouts[state.workoutIndex%28]),e=w.exercises.find(x=>x.name===name),g=exerciseGuide(name,e?.note||'');return head('EXERCISE GUIDE',name,g.summary)+`<section class="form narrow"><h3>How to do it</h3><ol>${g.steps.map(x=>`<li>${x}</li>`).join('')}</ol><h3>Technique cue</h3><p>${g.cues}</p><h3>Make it easier</h3><p>${g.easier}</p><button id="close-guide">Back to workout</button></section>`}
function buildIntervals(w){const steps=[];for(let r=1;r<=w.rounds;r++){w.exercises.forEach((e,i)=>{steps.push({kind:'work',name:e.name,note:e.note,seconds:w.workSeconds,round:r});if(!(r===w.rounds&&i===w.exercises.length-1))steps.push({kind:'rest',name:'Recover',note:'Next: '+(w.exercises[(i+1)%w.exercises.length]?.name||''),seconds:w.restSeconds,round:r})})}return steps}
function timerView(){const w=timer.workout||resolveWorkout(workouts[state.workoutIndex%28]),s=timer.steps[timer.index],pct=Math.round((timer.index/timer.steps.length)*100);return `<section class="timer-screen"><p class="eyebrow">WORKOUT ${w.id} · ROUND ${s.round} OF ${w.rounds}</p><div class="timer-progress"><i style="width:${pct}%"></i></div><p class="timer-kind">${s.kind==='rest'?'RECOVER':'MOVE'}</p><h1>${s.name}</h1>${s.kind==='work'?`<button id="timer-guide" class="secondary">How do I do this?</button>`:''}<div class="countdown">${Math.floor(timer.left/60)}:${String(timer.left%60).padStart(2,'0')}</div><p class="timer-note">${s.note}</p><div class="timer-actions"><button id="prev-step">← Previous</button><button id="toggle-timer">${timer.running?'Pause':'Start'}</button><button id="next-step">Skip →</button></div><button class="quit" id="quit-workout">Exit workout</button></section>`}
function startTimer(w){timer={workout:w,steps:buildIntervals(w),index:0,left:w.workSeconds,running:false,tick:null,endAt:null};view='timer';render()}
function advanceTimer(delta=1,autoStart=false){timer.index+=delta;if(timer.index<0)timer.index=0;if(timer.index>=timer.steps.length){finishWorkout();return}timer.left=timer.steps[timer.index].seconds;timer.endAt=null;cue(timer.steps[timer.index].kind==='rest'?440:660);render();if(autoStart&&state.autoProgress!==false){timer.running=true;timer.endAt=Date.now()+timer.left*1000;keepAwake();timer.tick=setInterval(refreshTimer,250);render()}}
async function keepAwake(){try{if('wakeLock'in navigator&&!wakeLock)wakeLock=await navigator.wakeLock.request('screen')}catch{}}
function releaseWake(){try{wakeLock?.release()}catch{}wakeLock=null}
function cue(freq=660){try{const C=window.AudioContext||window.webkitAudioContext,ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.05,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.12)}catch{}if(navigator.vibrate)navigator.vibrate(80)}
function refreshTimer(){if(!timer?.running||!timer.endAt)return;timer.left=Math.max(0,Math.ceil((timer.endAt-Date.now())/1000));const el=document.querySelector('.countdown');if(el)el.textContent=Math.floor(timer.left/60)+':'+String(timer.left%60).padStart(2,'0');if(timer.left<=0){clearInterval(timer.tick);timer.running=false;timer.endAt=null;advanceTimer(1,true)}}
async function runTimer(){timer.running=!timer.running;if(timer.running){timer.endAt=Date.now()+timer.left*1000;await keepAwake();cue(660);timer.tick=setInterval(refreshTimer,250)}else{refreshTimer();clearInterval(timer.tick);timer.endAt=null;releaseWake()}render()}
async function finishWorkout(){const w=timer?.workout||resolveWorkout(workouts[state.workoutIndex%28]);if(timer?.tick)clearInterval(timer.tick);releaseWake();timer=null;state.completedWorkouts.push({id:w.id,date:todayKey()});state.activities.push({name:w.title,minutes:w.minutes,date:todayKey(),type:'workout',workoutNumber:w.id});state.activeMinutes+=w.minutes;state.workoutIndex=(state.workoutIndex+1)%28;state.exerciseOverrides={};touchStreak(state);saveState(state);if(session)await syncMovement({type:'workout',workoutNumber:w.id,name:w.title,minutes:w.minutes,date:todayKey()});view='move';commit()}
function swimView(){return head('SWIM','Log your swim.','Record what you know. Time is enough; laps, distance and intensity are optional.')+`<section class="form narrow"><label>Minutes<input id="swim-minutes" type="number" min="1" placeholder="30"></label><label>Laps <small>optional</small><input id="swim-laps" type="number" min="0" placeholder="20"></label><label>Distance (km) <small>optional</small><input id="swim-distance" type="number" min="0" step="0.01" placeholder="0.5"></label><label>Intensity<select id="swim-intensity"><option value="">Not recorded</option><option value="easy">Easy</option><option value="moderate">Moderate</option><option value="hard">Hard</option></select></label><div class="auth-actions"><button id="save-swim">Save swim</button><button id="cancel-swim" class="secondary">Cancel</button></div></section>`}
function walkView(){const s=walkStats||{elapsedSeconds:0,km:0,pace:0,elevationGain:0},label={walk:'Walk',run:'Run',ride:'Bike Ride',hike:'Hike'}[gpsMode]||'Activity';return `<section class="walk-live"><p class="eyebrow">LIVE ${label.toUpperCase()}</p><h1>Keep moving.</h1><p class="privacy-note">GPS tracking is active only for this walk. Your route is private by default.</p><section class="walk-stats"><article><strong id="walk-time">${formatTime(s.elapsedSeconds)}</strong><span>time</span></article><article><strong id="walk-distance">${s.km.toFixed(2)}</strong><span>km</span></article><article><strong id="walk-pace">${formatPace(s.pace)}</strong><span>avg pace</span></article><article><strong id="walk-elevation">${Math.round(s.elevationGain)} m</strong><span>elevation gain</span></article></section><section class="live-map-wrap"><div id="live-route-map" class="route-map live-route-map"></div></section><section class="walk-guidance"><p class="eyebrow">GUIDANCE</p><h2>Steady walk</h2><p>Optional adaptive instructions will appear here. Always use your own judgement around roads, crossings and other hazards.</p></section><div class="walk-actions"><button id="finish-walk">Finish ${label}</button><button id="pause-gps" class="secondary">${s.paused?'Resume':'Pause'}</button><button id="cancel-walk" class="secondary">Cancel</button></div><p id="walk-error" class="hint"></p></section>`}
async function startGps(mode){gpsMode=mode;walkStats=null;liveMap=null;liveLine=null;liveMarker=null;view='walk';render();await keepAwake();walker=new ActivityTracker(stats=>{if(stats.error){const e=document.querySelector('#walk-error');if(e)e.textContent=stats.error;return}walkStats=stats;const t=document.querySelector('#walk-time'),d=document.querySelector('#walk-distance'),p=document.querySelector('#walk-pace'),g=document.querySelector('#walk-elevation');if(t)t.textContent=formatTime(stats.elapsedSeconds);if(d)d.textContent=stats.km.toFixed(2);if(p)p.textContent=formatPace(stats.pace);if(g)g.textContent=Math.round(stats.elevationGain)+' m';if(stats.points?.length){const el=document.querySelector('#live-route-map');if(el){if(!liveMap){const built=mapRoute(el,stats.points,{live:true});liveMap=built?.map;liveLine=built?.line;liveMarker=built?.marker}else{liveLine?.setLatLngs(stats.points.map(p=>[p.lat,p.lng]));const end=stats.points.at(-1);liveMarker?.setLatLng([end.lat,end.lng]);liveMap.panTo([end.lat,end.lng],{animate:false});liveMap.invalidateSize()}}}},{mode});try{walker.start()}catch(e){document.querySelector('#walk-error').textContent=e.message}}
async function finishWalk(){const s=walker?.stop();walker=null;liveMap=null;liveLine=null;liveMarker=null;releaseWake();if(s&&s.elapsedSeconds>0){const mins=Math.max(1,Math.round(s.elapsedSeconds/60));const label={walk:'GPS Walk',run:'GPS Run',ride:'GPS Bike Ride',hike:'GPS Hike'}[gpsMode]||'GPS Activity';const routePoints=(s.points||[]).filter(p=>p.accuracy<=50).map(p=>({lat:+p.lat.toFixed(6),lng:+p.lng.toFixed(6),at:p.at,accuracy:Math.round(p.accuracy)}));const item={name:label,minutes:mins,date:todayKey(),distanceKm:+s.km.toFixed(2),elevationGain:Math.round(s.elevationGain),type:gpsMode,routePoints};state.activities.push(item);state.activeMinutes+=mins;touchStreak(state);saveState(state);if(session)await syncMovement(item)}walkStats=null;view='move';render()}
function bindSwim(){document.querySelector('#cancel-swim').onclick=()=>{view='move';render()};document.querySelector('#save-swim').onclick=async()=>{const minutes=Math.round(Number(document.querySelector('#swim-minutes').value)),laps=Number(document.querySelector('#swim-laps').value)||null,distanceKm=Number(document.querySelector('#swim-distance').value)||null,intensity=document.querySelector('#swim-intensity').value||null;if(!(minutes>0))return;const item={name:'Swimming',minutes,date:todayKey(),type:'swim',laps,distanceKm,intensity};state.activities.push(item);state.activeMinutes+=minutes;touchStreak(state);saveState(state);if(session)await syncMovement(item);view='move';commit()}}
function bindWalk(){document.querySelector('#finish-walk').onclick=finishWalk;document.querySelector('#pause-gps').onclick=()=>{walker.paused?walker.resume():walker.pause();walkStats=walker.summary();render()};document.querySelector('#cancel-walk').onclick=()=>{walker?.stop();walker=null;liveMap=null;liveLine=null;liveMarker=null;releaseWake();walkStats=null;view='move';render()}}
function fuel(){
 const d=state.fuel[todayKey()]||{}, todays=(state.foodLog||[]).filter(x=>x.date===todayKey()), total=todays.reduce((n,x)=>n+x.points,0)
 return head('FUEL','Notice what you eat.','Food logging is for accountability, not perfection. Transform Points are a simple internal estimate based on food type and portion — not a clinical nutrition score.')+`<section class="cols"><article class="form"><h3>Log food</h3><label>What did you have?<input id="food-name" placeholder="e.g. toast and eggs"></label><label>Food type<select id="food-group">${foodGroups.map(x=>`<option value="${x[0]}">${x[2]}</option>`).join('')}</select></label><label>Portion<select id="food-portion">${portionOptions.map(x=>`<option value="${x[0]}">${x[2]}</option>`).join('')}</select></label><button id="log-food">Add food</button><p class="hint">Points are deliberately rough. They help you see patterns; they are not WeightWatchers Points and are not dietary advice.</p></article><article class="form"><h3>Today's food</h3><div class="points-total"><strong>${total}</strong><span>Transform Points</span></div>${todays.length?todays.slice().reverse().map(x=>`<div class="food-row"><span>${x.name}<small>${x.portion} · ${x.groupLabel}</small></span><strong>${x.points}</strong></div>`).join(''):'<p class="hint">Nothing logged yet.</p>'}</article></section><section class="choices">${fuelChoices.map(([id,label])=>`<button class="choice ${d[id]?'done':''}" data-fuel="${id}"><strong>${d[id]?'✓':'○'}</strong>${label}</button>`).join('')}<button class="choice water" id="water"><strong>+${state.hydrationByDate?.[todayKey()]||0}</strong>Log a drink of water</button></section>`
}
function progress(){
 const acts=state.activities||[], today=new Date(), days=Array.from({length:7},(_,i)=>{const d=new Date(today);d.setDate(today.getDate()-(6-i));return todayKey(d)}),
 weekly=days.map(d=>acts.filter(a=>a.date===d).reduce((n,a)=>n+(Number(a.minutes)||0),0)), weekTotal=weekly.reduce((a,b)=>a+b,0),
 n=state.completedWorkouts.length,p=Math.round(n/28*100), foods=state.foodLog||[], food7=foods.filter(x=>days.includes(x.date)),
 avgPoints=food7.length?Math.round(food7.reduce((n,x)=>n+x.points,0)/7):0, activeDays=days.filter(d=>acts.some(a=>a.date===d)).length,
 weights=(state.weighIns||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)), latest=weights.at(-1), first=weights[0],
 weightChange=latest&&first&&weights.length>1?latest.weightKg-first.weightKg:null, max=Math.max(1,...weekly)
 return head('PROGRESS','Momentum, visible.','Look for patterns across movement, consistency, food accountability and body progress — not one perfect number.')+`
 <section class="progress-summary">
  <article><span>Last 7 days</span><strong>${weekTotal}</strong><small>active minutes</small></article>
  <article><span>Consistency</span><strong>${activeDays}/7</strong><small>active days</small></article>
  <article><span>Current streak</span><strong>${state.streak}</strong><small>days</small></article>
  <article><span>Food awareness</span><strong>${food7.length}</strong><small>items logged</small></article>
 </section>
 <section class="trend-grid"><article class="trend-card"><div class="trend-head"><div><p class="eyebrow">MOVEMENT</p><h3>7-day activity</h3></div><strong>${weekTotal} min</strong></div><div class="bar-chart">${weekly.map((v,i)=>`<div><i style="height:${Math.max(4,v/max*100)}%"></i><span>${['S','M','T','W','T','F','S'][new Date(days[i]+'T12:00:00').getDay()]}</span><small>${v}</small></div>`).join('')}</div></article>
 <article class="trend-card"><p class="eyebrow">PROGRAMME</p><div class="programme-progress"><div class="ring" style="--p:${p}"><strong>${p}%</strong></div><div><h3>${n} workouts completed</h3><p>Next: workout ${state.workoutIndex%28+1} of 28</p></div></div></article>
 <article class="trend-card"><p class="eyebrow">FUEL</p><h3>Accountability, not a scorecard</h3><div class="metric-line"><strong>${avgPoints}</strong><span>average Transform Points / day this week</span></div><p class="hint">Use this to notice your own patterns over time. A lower or higher number is not automatically “better”.</p></article>
 <article class="trend-card"><p class="eyebrow">BODY</p><h3>${latest?latest.weightKg.toFixed(1)+' kg':'No weigh-in yet'}</h3><p>${weightChange===null?'Weight tracking is optional.':(weightChange>0?'+':'')+weightChange.toFixed(1)+' kg across your recorded weigh-ins.'}</p><button data-view="body" class="text-button">View body progress →</button></article></section>
 <section class="badges">${[['First Move',acts.length>=1],['100 Minutes',state.activeMinutes>=100],['Consistent 7',state.streak>=7],['28 Strong',n>=28]].map(([x,e])=>`<article class="${e?'earned':''}"><strong>${x}</strong><span>${e?'Earned':'Still ahead'}</span></article>`).join('')}</section>`
}
function together(){return head('TOGETHER','Better with a mate.','Choose someone in the programme as your workout mate. Your own workout sequence still carries over.')+`<section class="form narrow"><label>Workout mate<input id="mate" value="${state.mate}" placeholder="Choose a member"></label><button id="save-mate">Connect workout mate</button>${state.mate?`<p class="success">Connected with <strong>${state.mate}</strong>.</p>`:''}</section>`}
function equipment(){const owned=new Set(state.equipment||[]);return head('MY EQUIPMENT','Build around what you have.','Transform can use your available equipment when selecting exercises. Update this whenever your setup changes.')+`<section class="equipment-grid">${equipmentCatalog.map(([id,label])=>`<label class="equipment-item ${owned.has(id)?'selected':''}"><input type="checkbox" data-equipment="${id}" ${owned.has(id)?'checked':''}><span>${label}</span></label>`).join('')}</section><p class="hint equipment-note">No equipment? That is fine — bodyweight options remain available.</p>`}
function body(){
 const weights=(state.weighIns||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)), latest=weights.at(-1), value=latest?.weightKg, b=value&&state.heightCm?bmi(value,state.heightCm):null
 const points=weights.map((x,i)=>{const min=Math.min(...weights.map(w=>w.weightKg)),max=Math.max(...weights.map(w=>w.weightKg)),range=max-min||1;return `${weights.length===1?50:(i/(weights.length-1))*100},${90-((x.weightKg-min)/range)*80}`}).join(' ')
 return head('MY PROGRESS','More than one number.','Weight can be one optional measure of progress. Activity, consistency, strength, fitness and how you feel matter too.')+`<section class="body-grid"><article class="form"><h3>Weigh-in</h3><label>Weight (kg)<input id="weight-kg" type="number" min="20" max="400" step="0.1" value="${value||''}"></label><label>Height (cm) <small>optional, used for BMI</small><input id="height-cm" type="number" min="100" max="250" step="0.1" value="${state.heightCm||''}"></label><button id="save-weight">Save weigh-in</button><p class="hint">Weigh-ins are optional. BMI is shown as a screening calculation only and does not describe body composition, fitness or health by itself.</p></article><article class="body-summary"><p class="eyebrow">CURRENT</p><strong>${value?value.toFixed(1)+' kg':'—'}</strong><span>${b?'BMI '+b.toFixed(1):'Add height to calculate BMI'}</span></article></section>${weights.length?`<section class="weight-chart"><h3>Weight trend</h3><svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline points="${points}" fill="none" vector-effect="non-scaling-stroke"/></svg><div><span>${weights[0].date}</span><span>${weights.at(-1).date}</span></div></section>`:''}`
}
function direction(){return head('MY DIRECTION','What are you moving toward?','Private to you. Keep it simple and meaningful.')+`<section class="form narrow"><label>My direction<textarea id="direction" rows="5" placeholder="What would transformation look like for me?">${state.direction}</textarea></label><button id="save-direction">Save my direction</button></section>`}
function setup(){return head('SET UP','Make Transform yours.','Set your direction, equipment and workout preferences in one place.')+`<section class="setup-grid"><article class="form setup-direction"><p class="eyebrow">MY DIRECTION</p><h2>What am I moving toward?</h2><label><textarea id="direction" rows="5" placeholder="What would transformation look like for me?">${state.direction}</textarea></label><button id="save-direction">Save my direction</button><p class="hint">Private to you. Your direction also appears in My Journey so you can keep it in view.</p></article><article class="form setup-preferences"><p class="eyebrow">WORKOUT SETTINGS</p><h2>How I want workouts to run</h2><label class="preference-toggle"><input id="setup-auto-progress" type="checkbox" ${state.autoProgress!==false?'checked':''}><span><strong>Auto progression</strong><small>Move automatically through exercise and recovery intervals.</small></span></label><p class="hint">You can still pause, skip or go back at any time.</p></article></section><section class="setup-section"><div class="section-heading"><div><p class="eyebrow">MY EQUIPMENT</p><h2>Build around what I have.</h2></div><p>Transform uses these choices when selecting suitable exercise options.</p></div><div class="setup-equipment-grid">${equipmentCatalog.map(([id,label])=>`<label class="equipment-item ${(state.equipment||[]).includes(id)?'selected':''}"><input type="checkbox" data-equipment="${id}" ${(state.equipment||[]).includes(id)?'checked':''}><span>${label}</span></label>`).join('')}</div></section><section class="setup-help"><div><p class="eyebrow">HELP</p><h3>Need a refresher?</h3><p>Revisit the Getting Started guide whenever you need it.</p></div><button data-view="getting-started" class="text-button">Getting Started →</button></section>`}
function routePreview(a,id='route-map'){const pts=a.routePoints||[];if(pts.length<2)return '<div class="map-empty">Waiting for a reliable GPS route…</div>';return '<div id="'+id+'" class="route-map" aria-label="Route map"></div>'}
function mapRoute(el,pts,{live=false}={}){if(!el||!window.L||!pts?.length)return;const map=L.map(el,{zoomControl:true,attributionControl:true});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const line=L.polyline(pts.map(p=>[p.lat,p.lng]),{weight:5,color:'#7aa7ff'}).addTo(map);L.circleMarker([pts[0].lat,pts[0].lng],{radius:6,color:'#c9e86b',fillColor:'#c9e86b',fillOpacity:1}).addTo(map).bindTooltip('Start');const end=pts.at(-1),marker=L.circleMarker([end.lat,end.lng],{radius:10,color:'#fff',weight:3,fillColor:'#3478f6',fillOpacity:1}).addTo(map);if(!live)marker.bindTooltip('Finish');if(pts.length===1)map.setView([end.lat,end.lng],17);else map.fitBounds(line.getBounds(),{padding:[24,24],maxZoom:17});requestAnimationFrame(()=>{map.invalidateSize();setTimeout(()=>map.invalidateSize(),250)});return {map,line,marker}}
function routeHistory(){const gps=(state.activities||[]).filter(a=>a.routePoints?.length>1).slice().reverse();return `<section class="history route-history"><p class="eyebrow">SAVED ROUTES</p><h3>GPS activity history</h3>${gps.length?gps.map((a,i)=>'<button class="route-row" data-route="'+i+'"><span><strong>'+a.name+'</strong><small>'+a.date+'</small></span><span><strong>'+(a.distanceKm??'—')+' km</strong><small>'+a.minutes+' min</small></span></button>').join(''):'<p class="hint">Your completed GPS routes will appear here.</p>'}</section>`}
function activityHistory(){const items=(state.activities||[]).slice().reverse();return `<section class="history activity-history"><p class="eyebrow">ACTIVITY HISTORY</p><h3>Everything you've logged</h3>${items.length?items.map((a,i)=>'<div class="activity-row"><span><strong>'+a.name+'</strong><small>'+a.date+' · '+a.minutes+' min'+(a.distanceKm!=null?' · '+a.distanceKm+' km':'')+'</small></span><button data-share-activity="'+i+'" class="text-button">Share →</button></div>').join(''):'<p class="hint">Your completed workouts and activities will appear here.</p>'}</section>`}
function routeView(){const a=routeActivity;if(!a)return journey();return head('SAVED ROUTE',a.name,a.date)+`<section class="form route-detail">${routePreview(a)}<div class="route-stats"><div><strong>${a.distanceKm??'—'}</strong><span>km</span></div><div><strong>${a.minutes}</strong><span>minutes</span></div><div><strong>${a.elevationGain??0}</strong><span>m climbed</span></div></div><div class="route-actions"><button id="share-route">Share this workout</button><button id="close-route" class="secondary">Back to My Journey</button></div></section>`}
function privacyRoute(points){if(!points?.length)return [];if(points.length<8)return points.slice(Math.ceil(points.length*.2),Math.floor(points.length*.8));const trim=Math.max(2,Math.ceil(points.length*.12));return points.slice(trim,-trim)}
function shareView(){const a=shareActivity;if(!a)return journey();const gps=a.routePoints?.length>1,pts=shareMapMode==='full'?a.routePoints:shareMapMode==='privacy'?privacyRoute(a.routePoints):[];return head('SHARE THIS WORKOUT','Share the energy.','Choose exactly what you want other people to see before sharing.')+`<section class="share-card"><p class="eyebrow">TRANSFORM WITH ME</p><h2>${a.name}</h2><div class="share-stats"><strong>${a.minutes} min</strong>${a.distanceKm!=null?'<strong>'+a.distanceKm+' km</strong>':''}${a.elevationGain!=null?'<strong>'+a.elevationGain+' m climbed</strong>':''}</div>${gps&&shareMapMode!=='none'?routePreview({...a,routePoints:pts},'share-route-map'):''}<p>CONSISTENT. PERSISTENT. TARGETED.</p></section>${gps?'<section class="form share-options"><h3>Route privacy</h3><label><input type="radio" name="share-map" value="privacy" '+(shareMapMode==='privacy'?'checked':'')+'> Privacy route <small>Recommended — trims the beginning and end of the route.</small></label><label><input type="radio" name="share-map" value="full" '+(shareMapMode==='full'?'checked':'')+'> Full route <small>Includes your start and finish locations.</small></label><label><input type="radio" name="share-map" value="none" '+(shareMapMode==='none'?'checked':'')+'> No map</label></section>':''}<section class="form share-actions"><p class="hint">Preview what will be shared above. Your complete saved route remains private in Transform.</p><button id="native-share">Share workout</button><button id="cancel-share" class="secondary">Cancel</button></section>`}
async function shareWorkout(){const a=shareActivity,text=`I completed ${a.name} — ${a.minutes} active minutes${a.distanceKm!=null?' · '+a.distanceKm+' km':''}.\n\nConsistent. Persistent. Targeted.\nTransform With Me`,url=location.origin;if(navigator.share){try{await navigator.share({title:'Transform With Me',text,url});return}catch(e){if(e.name==='AbortError')return}}try{await navigator.clipboard.writeText(text+'\n'+url);syncMessage='Workout summary copied. You can paste it wherever you want to share it.';render()}catch{syncMessage='Sharing is not available in this browser.';render()}}
function progressPhotosView(){const photos=progressPhotos||[];return `<section class="history progress-photos"><p class="eyebrow">PROGRESS PHOTOS</p><h3>Your transformation, for you.</h3><p class="hint">Photos are private by default and are never shown to workout mates. Add them whenever you choose.</p><div class="photo-add"><label class="photo-button">Take Photo<input id="progress-photo-camera" type="file" accept="image/*" capture="user"></label><label class="photo-button secondary">Upload Photo<input id="progress-photo-file" type="file" accept="image/*"></label><select id="progress-photo-kind"><option value="progress">Progress photo</option><option value="starting">Starting photo</option></select></div>${photos.length?'<div class="photo-grid">'+photos.map((p,i)=>'<article><img src="'+p.url+'" alt="'+(p.kind==='starting'?'Starting':'Progress')+' photo"><strong>'+(p.kind==='starting'?'Starting photo':'Progress photo')+'</strong><small>'+p.photo_date+(p.weight_kg?' · '+p.weight_kg+' kg':'')+'</small><button class="text-button" data-delete-photo="'+i+'">Delete</button></article>').join('')+'</div>':'<p class="hint">No progress photos yet. Your first photo can become your Starting Photo.</p>'}</section>`}
function journeyStats(){const acts=state.activities||[],weights=(state.weighIns||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)),first=weights[0],last=weights.at(-1),start=acts.map(a=>a.date).filter(Boolean).sort()[0]||first?.date||todayKey(),days=Math.max(1,Math.floor((new Date(todayKey()+'T12:00:00')-new Date(start+'T12:00:00'))/86400000)+1),minutes=acts.reduce((n,a)=>n+(Number(a.minutes)||0),0),distance=acts.reduce((n,a)=>n+(Number(a.distanceKm)||0),0),weightChange=first&&last?+(last.weightKg-first.weightKg).toFixed(1):null,weightPct=first&&last&&first.weightKg?+((last.weightKg-first.weightKg)/first.weightKg*100).toFixed(1):null,startBmi=first&&state.heightCm?bmi(first.weightKg,state.heightCm):null,endBmi=last&&state.heightCm?bmi(last.weightKg,state.heightCm):null;return {days,minutes,distance:+distance.toFixed(1),workouts:acts.filter(a=>a.type==='workout').length,streak:state.streak,weightChange,weightPct,bmiChange:startBmi&&endBmi?+(endBmi-startBmi).toFixed(1):null}}
function selectedTransformationStats(){const s=journeyStats(),checked=[...document.querySelectorAll('[data-transform-stat]:checked')].map(x=>x.dataset.transformStat);return checked.map(k=>({key:k,label:{days:'Time transforming',workouts:'Workouts completed',minutes:'Active minutes',distance:'Distance travelled',weightChange:'Weight change',weightPct:'Weight change',bmiChange:'BMI change',streak:'Current streak'}[k],value:{days:s.days+' days',workouts:s.workouts,minutes:s.minutes+' min',distance:s.distance+' km',weightChange:(s.weightChange>0?'+':'')+s.weightChange+' kg',weightPct:(s.weightPct>0?'+':'')+s.weightPct+'%',bmiChange:(s.bmiChange>0?'+':'')+s.bmiChange,streak:s.streak+' days'}[k]}))}
function transformationPreviewView(){if(!transformationPreview)return '';const [a,b]=transformationPreview.photos;return `<section class="transformation-preview"><div class="transformation-card" id="transformation-card"><div class="transform-brand">TRANS<span>FORM</span><small>CONSISTENT. PERSISTENT. TARGETED.</small></div><div class="before-after"><figure><img src="${a.url}" alt="Before photo"><figcaption>${a.photo_date}</figcaption></figure><div class="journey-arrow">→</div><figure><img src="${b.url}" alt="After photo"><figcaption>${b.photo_date}</figcaption></figure></div><div class="transformation-stats">${transformationPreview.stats.map(x=>'<div><strong>'+x.value+'</strong><span>'+x.label+'</span></div>').join('')}</div></div><div class="share-actions"><button id="share-transformation">Share My Transformation</button><button id="close-transformation" class="text-button">Back to My Journey</button></div></section>`}
function loadShareImage(url){return new Promise((resolve,reject)=>{const img=new Image();img.crossOrigin='anonymous';img.onload=()=>resolve(img);img.onerror=reject;img.src=url})}
function coverImage(ctx,img,x,y,w,h){const scale=Math.max(w/img.width,h/img.height),sw=w/scale,sh=h/scale,sx=(img.width-sw)/2,sy=(img.height-sh)/2;ctx.drawImage(img,sx,sy,sw,sh,x,y,w,h)}
async function transformationImageFile(){if(!transformationPreview)return null;const [before,after]=await Promise.all(transformationPreview.photos.map(p=>loadShareImage(p.url)));const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=1200;const ctx=canvas.getContext('2d');const grad=ctx.createLinearGradient(0,0,1200,1200);grad.addColorStop(0,'#071b2a');grad.addColorStop(1,'#0b423d');ctx.fillStyle=grad;ctx.fillRect(0,0,1200,1200);ctx.fillStyle='#fff';ctx.font='900 58px system-ui,sans-serif';ctx.fillText('TRANS',70,88);const tw=ctx.measureText('TRANS').width;ctx.fillStyle='#9bea3b';ctx.fillText('FORM',70+tw,88);ctx.fillStyle='#d9e5e3';ctx.font='600 18px system-ui,sans-serif';ctx.fillText('CONSISTENT.  PERSISTENT.  TARGETED.',72,120);coverImage(ctx,before,70,170,500,590);coverImage(ctx,after,630,170,500,590);ctx.fillStyle='#9bea3b';ctx.font='900 54px system-ui,sans-serif';ctx.textAlign='center';ctx.fillText('→',600,480);ctx.font='600 22px system-ui,sans-serif';ctx.fillStyle='#fff';ctx.fillText(transformationPreview.photos[0].photo_date,320,800);ctx.fillText(transformationPreview.photos[1].photo_date,880,800);ctx.textAlign='left';const stats=transformationPreview.stats.slice(0,6),cols=3,cellW=340;stats.forEach((s,i)=>{const x=70+(i%cols)*370,y=870+Math.floor(i/cols)*135;ctx.fillStyle='#9bea3b';ctx.font='800 34px system-ui,sans-serif';ctx.fillText(String(s.value),x,y);ctx.fillStyle='#d9e5e3';ctx.font='500 18px system-ui,sans-serif';ctx.fillText(s.label,x,y+30)});ctx.fillStyle='#fff';ctx.font='700 22px system-ui,sans-serif';ctx.fillText('My Transform With Me journey',70,1150);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png',.95));return blob?new File([blob],'my-transform-journey.png',{type:'image/png'}):null}
async function shareTransformation(){if(!transformationPreview)return;const text='My Transform With Me journey — '+transformationPreview.stats.map(x=>x.label+': '+x.value).join(' · ');try{const file=await transformationImageFile();if(file&&navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({title:'My Transform With Me Journey',text,files:[file]});return}if(navigator.share){await navigator.share({title:'My Transform With Me Journey',text,url:location.origin});return}}catch(e){if(e?.name==='AbortError')return;console.warn('Transformation share failed',e)}try{await navigator.clipboard.writeText(text+' '+location.origin);syncMessage='Transformation summary copied to your clipboard.'}catch{syncMessage='Sharing is not available on this device.'}render()}
