 const signup=authMode==='signup'
 return `<section class="head"><p class="eyebrow">TRANSFORM WITH ME</p><h1>Start where you are.</h1><p>${signup?'Create your account and start your transformation.':'Sign in to keep your transformation progress with you.'}</p></section><section class="form narrow"><h3>${signup?'Create account':'Sign in'}</h3>${signup?'<label>Display name<input id="display-name" placeholder="Your name" autocomplete="name"></label>':''}<label>Email<input id="email" type="email" autocomplete="email"></label><label>Password<input id="password" type="password" autocomplete="${signup?'new-password':'current-password'}"></label><div class="auth-actions"><button id="auth-submit">${signup?'Create account':'Sign in'}</button></div><p class="auth-switch"><span>${signup?'Already have an account?':'New to Transform With Me?'}</span><button id="auth-toggle" type="button" class="text-action">${signup?'Sign in →':'Create an account →'}</button></p><p id="auth-message" class="hint"></p></section>`
