function render(){if(guideName){document.querySelector('#app').innerHTML=layout(guideView(guideName));document.querySelector('#close-guide').onclick=()=>{guideName=null;render()};return}if(supabase&&!session){document.querySelector('#app').innerHTML=layout(publicView==='vision'?visionView():authView());bindPublic();return}if(view==='walk'){document.querySelector('#app').innerHTML=layout(walkView());bindWalk();return}if(view==='swim'){document.querySelector('#app').innerHTML=layout(swimView());bindSwim();return}if(view==='timer'&&timer){document.querySelector('#app').innerHTML=layout(timerView());bindTimer();return}if(view==='route'&&routeActivity){document.querySelector('#app').innerHTML=layout(routeView());setTimeout(()=>mapRoute(document.querySelector('#route-map'),routeActivity.routePoints),0);document.querySelector('#share-route').onclick=()=>{shareActivity=routeActivity;shareMapMode='privacy';view='share';render()};document.querySelector('#close-route').onclick=()=>{routeActivity=null;view='journey';render()};return}if(view==='share'&&shareActivity){document.querySelector('#app').innerHTML=layout(shareView());const pts=shareMapMode==='full'?shareActivity.routePoints:privacyRoute(shareActivity.routePoints);if(shareActivity.routePoints?.length>1&&shareMapMode!=='none')setTimeout(()=>mapRoute(document.querySelector('#share-route-map'),pts),0);document.querySelectorAll('[name="share-map"]').forEach(x=>x.onchange=()=>{shareMapMode=x.value;render()});document.querySelector('#native-share').onclick=shareWorkout;document.querySelector('#cancel-share').onclick=()=>{view=shareActivity.routePoints?.length>1?'route':'journey';shareActivity=null;render()};return}const views={today,move,fuel,setup,journey,'getting-started':gettingStartedView};const renderView=views[view]||today;if(!views[view])view='today';document.querySelector('#app').innerHTML=layout(renderView());bind()}
function commit(){saveState(state);render()}
function cloudError(result,message='Saved on this device, but cloud sync failed.'){if(result?.error){syncMessage=message;return true}return false}
async function syncMovement(item){if(!session)return true;const activity=await addActivity(session.user.id,item);if(cloudError(activity))return false;const profile=await saveProfileProgress(session.user.id,{workout_index:state.workoutIndex,active_minutes:state.activeMinutes,streak:state.streak,last_active_date:state.lastActiveDate});if(cloudError(profile,'Activity saved, but your overall progress could not be updated in the cloud.'))return false;syncMessage='';return true}
async function hydrateCloud(){if(!supabase||!session?.user?.id)return;const uid=session.user.id;setStateUser(uid);state=loadState();const [cloud,well,photos]=await Promise.all([loadCloudState(uid),loadWellbeing(uid),loadProgressPhotos(uid)]);const loadErrors=[...(cloud.errors||[]),...(well.errors||[]),...(photos.error?[{source:'progress photos',error:photos.error}]:[])];if(loadErrors.length){const sources=[...new Set(loadErrors.map(x=>x.source).filter(Boolean))];syncMessage='Some cloud data could not be loaded'+(sources.length?' ('+sources.join(', ')+')':'')+'. Your device copy is still available.';console.warn('Transform cloud load errors',loadErrors.map(x=>({source:x.source,code:x.error?.code,message:x.error?.message})))}else syncMessage='';if(cloud.profile){state.workoutIndex=cloud.profile.workout_index??state.workoutIndex;state.activeMinutes=cloud.profile.active_minutes??state.activeMinutes;state.streak=cloud.profile.streak??state.streak;state.lastActiveDate=cloud.profile.last_active_date??state.lastActiveDate;state.direction=cloud.profile.direction??state.direction;state.equipment=cloud.profile.equipment??state.equipment;state.heightCm=cloud.profile.height_cm??state.heightCm;state.autoProgress=cloud.profile.auto_progress??state.autoProgress}if(!loadErrors.some(x=>x.source==='activities'))state.activities=cloud.activities.map(x=>({name:x.name,minutes:x.minutes,date:x.activity_date,type:x.activity_type,workoutNumber:x.workout_number,distanceKm:x.distance_km==null?undefined:Number(x.distance_km),elevationGain:x.elevation_gain_m??undefined,laps:x.laps??undefined,intensity:x.intensity??undefined,routePoints:x.route_points||undefined}));if(cloud.checkin){state.fuel[todayKey()]={'healthy-meal':cloud.checkin.healthy_meal,'snack':cloud.checkin.avoided_snacks,'drink':cloud.checkin.healthier_drinks,'fruit-veg':cloud.checkin.fruit_veg};state.hydrationByDate??={};state.hydrationByDate[todayKey()]=cloud.checkin.hydration||0}if(!cloud.checkin&&!loadErrors.some(x=>x.source==='daily check-in')){state.fuel[todayKey()]={};state.hydrationByDate??={};state.hydrationByDate[todayKey()]=0}if(!loadErrors.some(x=>x.source==='workout mates'))mateRows=cloud.mates||[];state.completedWorkouts=state.activities.filter(x=>x.type==='workout'&&x.workoutNumber).map(x=>({id:x.workoutNumber,date:x.date}));if(!loadErrors.some(x=>x.source==='food log'))state.foodLog=well.food.map(x=>({id:x.id,date:x.eaten_date,name:x.name,group:x.food_group,groupLabel:foodGroups.find(g=>g[0]===x.food_group)?.[2]||x.food_group,portion:x.portion,points:x.points}));if(!loadErrors.some(x=>x.source==='weigh-ins'))state.weighIns=well.weighIns.map(x=>({date:x.weigh_date,weightKg:Number(x.weight_kg)}));if(!photos.error)progressPhotos=photos.data||[];saveState(state);render()}
async function syncDailyCheckin(){const d=state.fuel[todayKey()]||{},r=await saveCheckin(session.user.id,todayKey(),{healthy_meal:!!d['healthy-meal'],avoided_snacks:!!d.snack,healthier_drinks:!!d.drink,fruit_veg:!!d['fruit-veg'],hydration:state.hydrationByDate?.[todayKey()]||0});if(cloudError(r))return false;const p=await saveProfileProgress(session.user.id,{streak:state.streak,last_active_date:state.lastActiveDate});if(cloudError(p,'Daily check-in saved, but your streak could not be updated in the cloud.'))return false;syncMessage='';return true}
function bindPublic(){document.querySelector('#vision-link')?.addEventListener('click',()=>{publicView='vision';render();scrollTo(0,0)});document.querySelector('#public-home')?.addEventListener('click',()=>{publicView='auth';render();scrollTo(0,0)});document.querySelector('#vision-join')?.addEventListener('click',()=>{publicView='auth';authMode='signup';render();scrollTo(0,0)});if(publicView==='auth')bindAuth()}
function bindAuth(){
 const email=()=>document.querySelector('#email').value.trim(), pass=()=>document.querySelector('#password').value, msg=document.querySelector('#auth-message')
 document.querySelector('#auth-toggle').onclick=()=>{authMode=authMode==='signin'?'signup':'signin';render()}
 const submit=document.querySelector('#auth-submit'), run=async()=>{if(authBusy)return;const e=email(),p=pass();if(!e||!p){msg.textContent='Enter your email and password.';return}authBusy=true;submit.disabled=true;submit.textContent=authMode==='signin'?'Signing in…':'Creating account…';try{
  if(authMode==='signin'){const {data,error}=await signIn(e,p);if(error){msg.textContent='We could not sign you in. Check your details and try again.';return}session=data.session;if(session)await hydrateCloud();render();return}
  const name=document.querySelector('#display-name').value.trim();if(!name){msg.textContent='Add your display name first.';return}
  const {data,error}=await signUp(e,p,name);if(error){msg.textContent='We could not create your account. Check your details and try again.';return}session=data.session
  if(session){await hydrateCloud();render()}else msg.textContent='Account created. Check your email to confirm it, then return here to sign in.'
 }finally{authBusy=false;if(document.body.contains(submit)){submit.disabled=false;submit.textContent=authMode==='signin'?'Sign in':'Create account'}}};submit.onclick=run;document.querySelector('#password')?.addEventListener('keydown',e=>{if(e.key==='Enter')run()})
}
function bindTimer(){document.querySelector('#timer-guide')?.addEventListener('click',()=>{if(timer.tick)clearInterval(timer.tick);if(timer.running)refreshTimer();timer.running=false;timer.endAt=null;releaseWake();guideName=timer.steps[timer.index].name;render()});document.querySelector('#toggle-timer').onclick=runTimer;document.querySelector('#next-step').onclick=()=>{if(timer.tick)clearInterval(timer.tick);timer.running=false;advanceTimer()};document.querySelector('#prev-step').onclick=()=>{if(timer.tick)clearInterval(timer.tick);timer.running=false;advanceTimer(-1)};document.querySelector('#quit-workout').onclick=()=>{if(timer.tick)clearInterval(timer.tick);releaseWake();timer=null;view='move';render()}}
function bindRoutes(){document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{const gps=(state.activities||[]).filter(a=>a.routePoints?.length>1).slice().reverse();routeActivity=gps[Number(b.dataset.route)];view='route';render();scrollTo(0,0)})}
function bind(){bindRoutes();document.querySelector('#share-transformation')?.addEventListener('click',shareTransformation);document.querySelector('#close-transformation')?.addEventListener('click',()=>{transformationPreview=null;render()});document.querySelector('#preview-transformation')?.addEventListener('click',()=>{if(transformationSelection.length!==2)return;const photos=transformationSelection.map(id=>progressPhotos.find(p=>p.id===id)).filter(Boolean).sort((a,b)=>a.photo_date.localeCompare(b.photo_date));if(photos.length!==2)return;transformationPreview={photos,stats:selectedTransformationStats()};render();scrollTo(0,0)});document.querySelectorAll('[data-transform-photo]').forEach(b=>b.onclick=()=>{const p=progressPhotos[+b.dataset.transformPhoto];if(!p)return;if(transformationSelection.includes(p.id))transformationSelection=transformationSelection.filter(x=>x!==p.id);else{if(transformationSelection.length>=2)transformationSelection.shift();transformationSelection.push(p.id)}render()});const uploadProgressPhoto=async input=>{const pf=input;if(!pf)return;const file=pf.files?.[0];if(!file||!session)return;syncMessage='Saving your private progress photo…';render();const kind=document.querySelector('#progress-photo-kind')?.value||'progress';const latest=(state.weighIns||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)).at(-1);const r=await addProgressPhoto(session.user.id,file,{kind,weightKg:latest?.weightKg||null});if(r.error){syncMessage='Your photo could not be saved. Your existing progress photos are unchanged.'}else{progressPhotos.push(r.data);syncMessage='Progress photo saved privately.'}render()};const pf=document.querySelector('#progress-photo-file');if(pf)pf.onchange=()=>uploadProgressPhoto(pf);const pc=document.querySelector('#progress-photo-camera');if(pc)pc.onchange=()=>uploadProgressPhoto(pc);document.querySelectorAll('[data-delete-photo]').forEach(b=>b.onclick=async()=>{const row=progressPhotos[+b.dataset.deletePhoto];if(!row||!confirm('Delete this progress photo?'))return;const r=await deleteProgressPhoto(row);if(r.error)syncMessage='That photo could not be deleted.';else{progressPhotos=progressPhotos.filter(x=>x.id!==row.id);syncMessage='Progress photo deleted.'}render()});document.querySelectorAll('[data-share-activity]').forEach(b=>b.onclick=()=>{const items=(state.activities||[]).slice().reverse();shareActivity=items[+b.dataset.shareActivity];shareMapMode='privacy';view='share';render()});document.querySelector('#install-app')?.addEventListener('click',async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;render()});document.querySelector('#menu-toggle')?.addEventListener('click',()=>{mobileNavOpen=!mobileNavOpen;render()});document.querySelectorAll('header nav [data-view]').forEach(b=>b.addEventListener('click',()=>{mobileNavOpen=false}));
 document.querySelector('#sign-out')?.addEventListener('click',async()=>{await signOut();session=null;setStateUser(null);state=resetState();view='today';render()})
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{mobileNavOpen=false;view=b.dataset.view;render();scrollTo(0,0)})
 document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>{guideName=b.dataset.guide;render()});document.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>{const w=resolveWorkout(workouts[state.workoutIndex%28]),i=+b.dataset.swap,slot=w.exercises[i],opts=availableOptions(slot.category,state.equipment||[],levelForWorkout(w.id));if(opts.length<2)return;const current=opts.findIndex(x=>x.name===slot.name),next=opts[(current+1)%opts.length];state.exerciseOverrides??={};state.exerciseOverrides[`${w.id}:${i}`]=next.name;saveState(state);render()})
 document.querySelector('#auto-progress')?.addEventListener('change',async e=>{state.autoProgress=e.target.checked;saveState(state);if(session)cloudError(await saveProfileProgress(session.user.id,{auto_progress:state.autoProgress}))});document.querySelector('#setup-auto-progress')?.addEventListener('change',async e=>{state.autoProgress=e.target.checked;saveState(state);if(session)cloudError(await saveProfileProgress(session.user.id,{auto_progress:state.autoProgress}));render()});document.querySelector('#start-workout')?.addEventListener('click',()=>startTimer(resolveWorkout(workouts[state.workoutIndex%28])))
 document.querySelectorAll('[data-gps]').forEach(b=>b.addEventListener('click',()=>startGps(b.dataset.gps)))
 document.querySelector('#quick-swim')?.addEventListener('click',()=>{view='swim';render()})
 document.querySelectorAll('[data-equipment]').forEach(x=>x.onchange=async()=>{const set=new Set(state.equipment||[]);x.checked?set.add(x.dataset.equipment):set.delete(x.dataset.equipment);state.equipment=[...set];if(session)cloudError(await saveProfileProgress(session.user.id,{equipment:state.equipment}));commit()})
 document.querySelectorAll('[data-mate-accept]').forEach(b=>b.onclick=async()=>{const r=await updateWorkoutMate(b.dataset.mateAccept,'accepted');if(r.error){syncMessage='Workout mate request could not be accepted.';render();return}await hydrateCloud()})
 document.querySelectorAll('[data-mate-decline]').forEach(b=>b.onclick=async()=>{const r=await updateWorkoutMate(b.dataset.mateDecline,'declined');if(r.error){syncMessage='Workout mate request could not be declined.';render();return}await hydrateCloud()})
 document.querySelector('#find-mate')?.addEventListener('click',async()=>{const panel=document.querySelector('#mate-panel');panel.innerHTML='<p class="hint">Loading members…</p>';const r=await loadMemberDirectory();if(r.error){panel.innerHTML='<p class="hint">Member list could not be loaded right now.</p>';return}memberDirectory=r.data||[];const connected=new Set(mateRows.filter(x=>x.status==='accepted').map(x=>x.requester_id===session.user.id?x.mate_id:x.requester_id));panel.innerHTML=memberDirectory.length?'<div class="member-list">'+memberDirectory.map(m=>'<div><strong>'+m.display_name+'</strong>'+(connected.has(m.user_id)?'<span class="success">Connected</span>':'<button data-mate-id="'+m.user_id+'">Connect</button>')+'</div>').join('')+'</div>':'<p class="hint">No other members are available yet.</p>';panel.querySelectorAll('[data-mate-id]').forEach(b=>b.onclick=async()=>{const r=await requestWorkoutMate(session.user.id,b.dataset.mateId);if(r.error){syncMessage='Workout mate request could not be sent.';render();return}b.outerHTML='<span class="hint">Request sent</span>'})})
 document.querySelector('#log')?.addEventListener('click',async()=>{const name=document.querySelector('#activity').value.trim(),minutes=+document.querySelector('#minutes').value;if(!name||minutes<1)return;state.activities.push({name,minutes,date:todayKey()});state.activeMinutes+=minutes;touchStreak(state);saveState(state);if(session)await syncMovement({type:'activity',name,minutes,date:todayKey()});commit()})
 document.querySelector('#log-food')?.addEventListener('click',async()=>{const name=document.querySelector('#food-name').value.trim(),group=document.querySelector('#food-group').value,portion=document.querySelector('#food-portion').value;if(!name)return;const groupLabel=foodGroups.find(x=>x[0]===group)?.[2]||group;const item={id:Date.now(),date:todayKey(),name,group,groupLabel,portion,points:estimatePoints(group,portion)};state.foodLog.push(item);touchStreak(state);saveState(state);if(session)cloudError(await addFood(session.user.id,item));commit()})
 document.querySelector('#save-weight')?.addEventListener('click',async()=>{const weight=Number(document.querySelector('#weight-kg').value),height=Number(document.querySelector('#height-cm').value);if(!(weight>0))return;if(height>0)state.heightCm=height;state.weighIns=state.weighIns.filter(x=>x.date!==todayKey());state.weighIns.push({date:todayKey(),weightKg:weight});saveState(state);if(session){cloudError(await saveWeighIn(session.user.id,todayKey(),weight));cloudError(await saveProfileProgress(session.user.id,{height_cm:state.heightCm}))}commit()})
 document.querySelectorAll('[data-fuel]').forEach(b=>b.onclick=async()=>{const d=todayKey();state.fuel[d]??={};state.fuel[d][b.dataset.fuel]=!state.fuel[d][b.dataset.fuel];touchStreak(state);saveState(state);if(session)await syncDailyCheckin();commit()})
 document.querySelector('#water')?.addEventListener('click',async()=>{state.hydrationByDate??={};state.hydrationByDate[todayKey()]=(state.hydrationByDate[todayKey()]||0)+1;touchStreak(state);saveState(state);if(session)await syncDailyCheckin();commit()})
 document.querySelector('#save-mate')?.addEventListener('click',()=>{state.mate=document.querySelector('#mate').value.trim();commit()})
 document.querySelector('#save-direction')?.addEventListener('click',async()=>{state.direction=document.querySelector('#direction').value.trim();saveState(state);if(session)cloudError(await saveProfileProgress(session.user.id,{direction:state.direction}));commit()})
}
async function start(){session=await getSession();if(session)await hydrateCloud();if(supabase){supabase.auth.onAuthStateChange(async(_event,s)=>{session=s;if(session)await hydrateCloud();else{setStateUser(null);state=resetState();render()}})}render()}
start()

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(view==='getting-started')render()})
window.addEventListener('appinstalled',()=>{installPrompt=null;if(view==='getting-started')render()})

document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){if(timer?.running)keepAwake();refreshTimer()}})
